//! Raw FFI bindings to the NVIDIA Video Codec SDK encoder API (NVENC).
//!
//! * `bindings.rs` is generated by bindgen from FFmpeg's `nv-codec-headers`
//!   (MIT-licensed copy of `nvEncodeAPI.h`), see `scripts/regen.sh`.
//! * `guids.rs` holds codec / profile / preset GUIDs (bindgen can't emit them).
//! * Struct version helpers mirror the `*_VER` macros from the header.
//!
//! The bindings were generated for x86_64; the struct layout of the header
//! is identical on Windows x64 and Linux x64 (fixed-width integers, pointers,
//! enums as 32-bit ints), and on x86_64 `extern "C"` == `__stdcall`.

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code
)]
#![allow(clippy::all)]

mod bindings;
mod guids;

pub use bindings::*;
pub use guids::*;

/// `NVENCAPI_VERSION` = major | (minor << 24).
pub const NVENCAPI_VERSION: u32 = NVENCAPI_MAJOR_VERSION | (NVENCAPI_MINOR_VERSION << 24);

/// `NVENCAPI_STRUCT_VERSION(ver)`.
pub const fn struct_version(ver: u32) -> u32 {
    NVENCAPI_VERSION | (ver << 16) | (0x7 << 28)
}

// Versions copied from nvEncodeAPI.h (SDK 13.0). When regenerating bindings
// for a new SDK, re-check every value below against the header.
pub const NV_ENC_CAPS_PARAM_VER: u32 = struct_version(1);
pub const NV_ENC_CREATE_BITSTREAM_BUFFER_VER: u32 = struct_version(1);
pub const NV_ENC_RC_PARAMS_VER: u32 = struct_version(1);
pub const NV_ENC_CONFIG_VER: u32 = struct_version(9) | (1 << 31);
pub const NV_ENC_INITIALIZE_PARAMS_VER: u32 = struct_version(7) | (1 << 31);
pub const NV_ENC_RECONFIGURE_PARAMS_VER: u32 = struct_version(2) | (1 << 31);
pub const NV_ENC_PRESET_CONFIG_VER: u32 = struct_version(5) | (1 << 31);
pub const NV_ENC_PIC_PARAMS_VER: u32 = struct_version(7) | (1 << 31);
pub const NV_ENC_LOCK_BITSTREAM_VER: u32 = struct_version(2) | (1 << 31);
pub const NV_ENC_MAP_INPUT_RESOURCE_VER: u32 = struct_version(4);
pub const NV_ENC_REGISTER_RESOURCE_VER: u32 = struct_version(5);
pub const NV_ENC_OPEN_ENCODE_SESSION_EX_PARAMS_VER: u32 = struct_version(1);
pub const NV_ENCODE_API_FUNCTION_LIST_VER: u32 = struct_version(2);

/// `NVENCSTATUS NvEncodeAPICreateInstance(NV_ENCODE_API_FUNCTION_LIST*)`
pub type PFN_NvEncodeAPICreateInstance =
    unsafe extern "C" fn(function_list: *mut NV_ENCODE_API_FUNCTION_LIST) -> NVENCSTATUS;

/// `NVENCSTATUS NvEncodeAPIGetMaxSupportedVersion(uint32_t*)`
/// Returned value is `(major << 4) | minor`.
pub type PFN_NvEncodeAPIGetMaxSupportedVersion =
    unsafe extern "C" fn(version: *mut u32) -> NVENCSTATUS;

/// Name of the driver library that exports the entry points.
#[cfg(windows)]
pub const NVENC_LIBRARY: &str = "nvEncodeAPI64.dll";
#[cfg(not(windows))]
pub const NVENC_LIBRARY: &str = "libnvidia-encode.so.1";

/// Loaded driver library with the two exported entry points.
pub struct NvencLibrary {
    _lib: libloading::Library,
    pub create_instance: PFN_NvEncodeAPICreateInstance,
    pub get_max_supported_version: PFN_NvEncodeAPIGetMaxSupportedVersion,
}

impl NvencLibrary {
    /// Loads the NVENC driver library.
    ///
    /// # Safety
    /// Loading a library runs its initialisation code.
    pub unsafe fn load() -> Result<Self, libloading::Error> {
        unsafe {
            let lib = libloading::Library::new(NVENC_LIBRARY)?;
            let create_instance =
                *lib.get::<PFN_NvEncodeAPICreateInstance>(b"NvEncodeAPICreateInstance\0")?;
            let get_max_supported_version = *lib.get::<PFN_NvEncodeAPIGetMaxSupportedVersion>(
                b"NvEncodeAPIGetMaxSupportedVersion\0",
            )?;
            Ok(Self {
                _lib: lib,
                create_instance,
                get_max_supported_version,
            })
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn api_version_matches_header() {
        assert_eq!(NVENCAPI_MAJOR_VERSION, 13);
        assert_eq!(NVENCAPI_MINOR_VERSION, 0);
        assert_eq!(NVENCAPI_VERSION, 13);
    }

    #[test]
    fn hevc_guid_is_correct() {
        assert_eq!(NV_ENC_CODEC_HEVC_GUID.Data1, 0x790cdc88);
    }

    #[test]
    fn struct_sizes_are_sane() {
        // Pointer-sized fields: layout was generated for x86_64.
        assert_eq!(core::mem::size_of::<usize>(), 8);
        assert!(core::mem::size_of::<NV_ENC_CONFIG>() > 3000);
    }
}
